```tsx
import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'sonner';
import { CheckIcon, AlertTriangleIcon, XIcon } from 'lucide-react';

type Message = {
  id: string;
  text: string;
  type: 'success' | 'warning' | 'error';
  timestamp: Date;
};

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isClearVisible, setIsClearVisible] = useState(false);

  // Mock data for initial messages
  useEffect(() => {
    const initialMessages: Message[] = [
      {
        id: '1',
        text: 'Your profile has been updated successfully!',
        type: 'success',
        timestamp: new Date(Date.now() - 300000),
      },
      {
        id: '2',
        text: 'Warning: Low battery detected.',
        type: 'warning',
        timestamp: new Date(Date.now() - 180000),
      },
      {
        id: '3',
        text: 'An unexpected error occurred.',
        type: 'error',
        timestamp: new Date(Date.now() - 120000),
      },
    ];
    setMessages(initialMessages);
  }, []);

  const handleButtonClick = (type: 'success' | 'warning' | 'error') => {
    const messageText = {
      success: 'Operation completed successfully!',
      warning: 'This is a warning message.',
      error: 'An error has occurred. Please try again.',
    }[type];

    const newMessage: Message = {
      id: `${Date.now()}`,
      text: messageText,
      type,
      timestamp: new Date(),
    };

    setMessages((prev) => [newMessage, ...prev.slice(0, 4)]); // Keep only last 5

    toast[type === 'success' ? 'success' : type === 'warning' ? 'warning' : 'error'](
      messageText,
      {
        style: {
          background: type === 'success' ? '#d1fae5' : type === 'warning' ? '#fff7e6' : '#fee2e2',
          color: type === 'success' ? '#059650' : type === 'warning' ? '#d97706' : '#dc2626',
          border: type === 'success' ? '1px solid #a3e635' : type === 'warning' ? '1px solid #f59e0b' : '1px solid #ef4444',
          borderRadius: '0.5rem',
          padding: '0.75rem',
          boxShadow: '0 1px 2px rgba(0,0,0,0.1)',
        },
      }
    );
  };

  const handleClear = () => {
    setMessages([]);
    setIsClearVisible(false);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex flex-col">
      <header className="p-6 border-b border-slate-200 bg-white/80 backdrop-blur-sm">
        <h1 className="text-2xl font-bold text-slate-800">Notification Center</h1>
        <p className="text-sm text-slate-500 mt-1">Manage and view your recent notifications</p>
      </header>

      <main className="flex-1 p-6 flex flex-col md:flex-row gap-8 items-start justify-center max-w-6xl mx-auto">
        <div className="flex flex-col gap-4 w-full md:w-1/3">
          <button
            onClick={() => handleButtonClick('success')}
            className="flex items-center gap-3 px-5 py-3 bg-green-500 hover:bg-green-600 text-white font-medium rounded-lg transition-colors duration-200 shadow-sm hover:shadow-md"
          >
            <CheckIcon className="w-5 h-5" />
            Success
          </button>

          <button
            onClick={() => handleButtonClick('warning')}
            className="flex items-center gap-3 px-5 py-3 bg-yellow-500 hover:bg-yellow-600 text-white font-medium rounded-lg transition-colors duration-200 shadow-sm hover:shadow-md"
          >
            <AlertTriangleIcon className="w-5 h-5" />
            Warning
          </button>

          <button
            onClick={() => handleButtonClick('error')}
            className="flex items-center gap-3 px-5 py-3 bg-red-500 hover:bg-red-600 text-white font-medium rounded-lg transition-colors duration-200 shadow-sm hover:shadow-md"
          >
            <XIcon className="w-5 h-5" />
            Error
          </button>

          {messages.length > 0 && (
            <button
              onClick={handleClear}
              className="mt-4 px-4 py-2 bg-gray-500 hover:bg-gray-600 text-white font-medium rounded-lg transition-colors duration-200 text-sm"
            >
              Clear All
            </button>
          )}
        </div>

        <div className="w-full md:w-2/3 bg-white/80 backdrop-blur-sm p-6 rounded-xl shadow-md border border-slate-200">
          <h2 className="text-xl font-semibold text-slate-800 mb-4">Recent Messages</h2>
          {messages.length === 0 ? (
            <p className="text-slate-500 text-center py-8">No messages yet. Click a button above to get started.</p>
          ) : (
            <ul className="space-y-3 max-h-96 overflow-y-auto">
              {messages.map((msg) => (
                <li
                  key={msg.id}
                  className={`p-4 rounded-lg border-l-4 ${
                    msg.type === 'success'
                      ? 'bg-green-50 border-green-500 text-green-800'
                      : msg.type === 'warning'
                      ? 'bg-yellow-50 border-yellow-500 text-yellow-800'
                      : 'bg-red-50 border-red-500 text-red-800'
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <div className="flex items-center gap-2">
                      {msg.type === 'success' && <CheckIcon className="w-4 h-4" />}
                      {msg.type === 'warning' && <AlertTriangleIcon className="w-4 h-4" />}
                      {msg.type === 'error' && <XIcon className="w-4 h-4" />}
                      <span className="font-medium">{msg.text}</span>
                    </div>
                    <span className="text-xs text-slate-500">
                      {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </span>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>
      </main>

      <ToastContainer
        position="top-right"
        theme="light"
        className="fixed top-4 right-4 z-50"
        toastOptions={{
          style: {
            maxWidth: '300px',
            minWidth: '200px',
            borderRadius: '0.5rem',
            border: '1px solid #e5e7eb',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
          },
        }}
      />
    </div>
  );
};

export default App;
```

